G = {"api": ["core", "cli"], "core": ["util"], "cli": ["core", "util"], "util": []}
LIMIT = 2

def fan_out(mod):
    return len(G[mod])

def fan_in(mod):
    return sum(1 for deps in G.values() if mod in deps)

for m in sorted(G):
    tag = "  <-- smell candidate" if fan_out(m) > LIMIT else ""
    print(f"{m} fan-in {fan_in(m)} fan-out {fan_out(m)}{tag}")

